#!/usr/bin/env bash
# SPDX-License-Identifier: MIT
# Atlas KubeKit | By Atlas Richie
# BEGIN ATLAS KUBEKIT VERSION (generated by scripts/update-version.py)
ATLAS_KUBEKIT_VERSION='0.2.0'
if [ "${1:-}" = --version ] || [ "${1:-}" = -V ]; then
  printf 'Atlas KubeKit %s\n' "$ATLAS_KUBEKIT_VERSION"
  exit 0
fi
# END ATLAS KUBEKIT VERSION
#
# setup-lb.sh —— 在 lb1/lb2 上部署 kube-apiserver 与可选应用入口负载均衡
#
#   HAProxy   : TCP round-robin across registered control-plane nodes
#   Keepalived: VRRP VIP failover across registered load balancers
#
# Usage: invoked by 02-deploy-cluster.sh with CP_BACKENDS and LB_PRIORITY.
# Optional APP_INGRESS_VIP reserves an application VIP during cluster setup.
# App routes remain managed by 05-manage-lb.sh after their NodePort exists.

set -euo pipefail
[ "${BASH_VERSINFO[0]}" -ge 4 ] || { printf '[ERROR] Bash 4 or newer is required\n' >&2; exit 2; }

red()  { printf '\033[31m%s\033[0m\n' "$*"; }
grn()  { printf '\033[32m%s\033[0m\n' "$*"; }
inf()  { printf '\033[36m==> %s\033[0m\n' "$*"; }
warn() { printf '\033[33m[WARN] %s\033[0m\n' "$*"; }
die()  { printf '\033[31m[ERROR] %s\033[0m\n' "$*"; exit 1; }
pass() { printf '  \033[32mOK\033[0m %s\n' "$*"; }

# Package installation and the health-check permissions are retained on failure.
# Managed configuration and service state are restored if applying it fails.
TMP_CFG="" TMP_KEEP="" TMP_STATE="" TMP_CHECK="" TMP_SYSCTL=""
ROLLBACK_REQUIRED=0
BACKUP_DIR=""
NONLOCAL_CONF=/etc/sysctl.d/99-atlas-kubekit-lb.conf
NONLOCAL_BIND_BEFORE=""
NONLOCAL_BIND_TOUCHED=0
CONFIG_PATHS=(/etc/haproxy/haproxy.cfg /etc/keepalived/keepalived.conf /etc/atlas-kubekit/lb-manager.json "$NONLOCAL_CONF")
SERVICES=(haproxy keepalived)
SERVICE_ACTIVE=(0 0)
SERVICE_TOUCHED=(0 0)
SERVICE_ENABLED=(0 0)
SERVICE_ENABLE_TOUCHED=(0 0)
cleanup() {
  local status=$? i path
  trap - EXIT
  if [ "$ROLLBACK_REQUIRED" -eq 1 ]; then
    warn "LB configuration failed; restoring the previous files and service state (backup: $BACKUP_DIR)"
    for i in "${!CONFIG_PATHS[@]}"; do
      path="${CONFIG_PATHS[$i]}"
      if [ -e "$BACKUP_DIR/$i" ] || [ -L "$BACKUP_DIR/$i" ]; then
        if ! rm -f "$path" || ! cp -a "$BACKUP_DIR/$i" "$path"; then
          warn "Could not restore $path; recover it from $BACKUP_DIR/$i"
        fi
      elif [ -e "$BACKUP_DIR/$i.absent" ]; then
        rm -f "$path" || warn "Could not remove the newly created file $path"
      fi
    done
    for i in "${!SERVICES[@]}"; do
      [ "${SERVICE_TOUCHED[$i]}" -eq 1 ] || continue
      if [ "${SERVICE_ACTIVE[$i]}" -eq 1 ]; then
        systemctl restart "${SERVICES[$i]}" || warn "Could not restart the restored ${SERVICES[$i]} service"
      else
        systemctl stop "${SERVICES[$i]}" || warn "Could not stop the newly started ${SERVICES[$i]} service"
      fi
    done
    if [ "$NONLOCAL_BIND_TOUCHED" -eq 1 ]; then
      sysctl -w "net.ipv4.ip_nonlocal_bind=$NONLOCAL_BIND_BEFORE" >/dev/null \
        || warn 'Could not restore the previous net.ipv4.ip_nonlocal_bind value'
    fi
    for i in "${!SERVICES[@]}"; do
      if [ "${SERVICE_ENABLE_TOUCHED[$i]}" -eq 1 ] && [ "${SERVICE_ENABLED[$i]}" -eq 0 ]; then
        systemctl disable "${SERVICES[$i]}" || warn "Could not restore the disabled boot state of ${SERVICES[$i]}"
      fi
    done
    [ "$status" -ne 0 ] || status=1
  fi
  for path in "$TMP_CFG" "$TMP_KEEP" "$TMP_STATE" "$TMP_CHECK" "$TMP_SYSCTL"; do
    [ -z "$path" ] || rm -f "$path" || true
  done
  exit "$status"
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

valid_ipv4() {
  local value="$1" octet
  local -a octets
  [[ "$value" =~ ^[0-9]{1,3}(\.[0-9]{1,3}){3}$ ]] || return 1
  IFS=. read -r -a octets <<< "$value"
  for octet in "${octets[@]}"; do
    [[ "$octet" = 0 || "$octet" != 0* ]] && [ "$octet" -le 255 ] || return 1
  done
}

# ============================================================== 参数
VIP="${VIP:-10.20.1.9}"
API_PORT="${API_PORT:-6443}"
IFACE="${IFACE:-enp6s18}"
VRRP_ID="${VRRP_ID:-51}"
# Every LB must use the same VRRP password to avoid competing VIP owners.
AUTH_PASS="${AUTH_PASS:-}"
CP1="${CP1:-10.20.1.22}"
CP2="${CP2:-10.20.1.23}"
CP3="${CP3:-10.20.1.24}"
CP_BACKENDS="${CP_BACKENDS:-cp1=$CP1 cp2=$CP2 cp3=$CP3}"
APP_INGRESS_VIP="${APP_INGRESS_VIP:-}"
LB_PRIORITY="${LB_PRIORITY:-}"
MODE="master"
CHECK_ONLY=0

SELF_IP=""
for a in "$@"; do
  case "$a" in
    --slave) MODE="slave" ;;
    --master) MODE="master" ;;
    --check-only) CHECK_ONLY=1 ;;
    --*) die "Unknown argument: $a (use --slave or --master)" ;;
    *) [ -z "$SELF_IP" ] || die "Specify only one local IP"; SELF_IP="$a" ;;
  esac
done

if [ -z "$SELF_IP" ]; then
  SELF_IP="$(ip -o -4 addr show "$IFACE" | awk '{print $4}' | cut -d/ -f1 | head -1)"
fi
[ -n "$SELF_IP" ] || die "Cannot detect local IP; run: sudo bash $0 <local-IP>"
valid_ipv4 "$SELF_IP" && valid_ipv4 "$VIP" || die 'Local IP and VIP must be valid IPv4 addresses'
[[ "$IFACE" =~ ^[a-zA-Z0-9_.:-]+$ ]] || die 'Invalid network interface'
ip -o -4 addr show "$IFACE" | grep -Fq " $SELF_IP/" || die 'Local IP is not assigned to the selected network interface'
[[ "$API_PORT" =~ ^[0-9]+$ ]] && [ "$API_PORT" -ge 1 ] && [ "$API_PORT" -le 65535 ] && [ "$API_PORT" -ne 7000 ] \
  || die 'API_PORT must be 1-65535 and must differ from stats port 7000'
[[ "$VRRP_ID" =~ ^[0-9]+$ ]] && [ "$VRRP_ID" -ge 1 ] && [ "$VRRP_ID" -le 255 ] || die "VRRP_ID must be an integer from 1 to 255"
[[ "$AUTH_PASS" =~ ^[A-Za-z0-9._-]{1,8}$ ]] || die "VRRP auth_pass must contain 1-8 letters, digits, or ._- characters (Keepalived uses at most 8)"

if [ -n "$LB_PRIORITY" ]; then PRIORITY="$LB_PRIORITY"; elif [ "$MODE" = master ]; then PRIORITY=150; else PRIORITY=100; fi
[[ "$PRIORITY" =~ ^[0-9]+$ ]] && [ "$PRIORITY" -ge 1 ] && [ "$PRIORITY" -le 254 ] || die 'LB priority must be 1-254'
BACKEND_NAMES=() BACKEND_IPS=()
declare -A SEEN_BACKENDS
for backend in $CP_BACKENDS; do
  [[ "$backend" =~ ^(cp[1-9][0-9]*)=([0-9]{1,3}(\.[0-9]{1,3}){3})$ ]] || die "Invalid control-plane backend: $backend"
  cp_name="${BASH_REMATCH[1]}"; cp_ip="${BASH_REMATCH[2]}"
  valid_ipv4 "$cp_ip" || die "Invalid control-plane backend address: $cp_name"
  [ -z "${SEEN_BACKENDS[$cp_name]:-}" ] || die "Duplicate control-plane backend: $cp_name"
  [ "$VIP" != "$cp_ip" ] && [ "$SELF_IP" != "$cp_ip" ] || die "Backend $cp_name conflicts with VIP or local LB IP"
  SEEN_BACKENDS[$cp_name]=1
  BACKEND_NAMES+=("$cp_name"); BACKEND_IPS+=("$cp_ip")
done
[ "${#BACKEND_NAMES[@]}" -ge 1 ] || die 'At least one control-plane backend is required'

if [ -n "$APP_INGRESS_VIP" ]; then
  valid_ipv4 "$APP_INGRESS_VIP" || die 'APP_INGRESS_VIP must be a valid IPv4 address'
  [ "$APP_INGRESS_VIP" != "$VIP" ] && [ "$APP_INGRESS_VIP" != "$SELF_IP" ] \
    || die 'Application ingress VIP must differ from the API VIP and local LB address'
  for backend_ip in "${BACKEND_IPS[@]}"; do
    [ "$APP_INGRESS_VIP" != "$backend_ip" ] || die 'Application ingress VIP must not match a control-plane node address'
  done
fi

[ "$(id -u)" -eq 0 ] || die "Run as root"
export DEBIAN_FRONTEND=noninteractive

grn "============================================================"
grn " LB setup: local=$SELF_IP  VIP=$VIP  role=$MODE(priority=$PRIORITY)"
grn " Backends: $CP_BACKENDS :$API_PORT"
grn "============================================================"

# VIP 不能等于任何一台后端，也不能等于本机
for ip in "${BACKEND_IPS[@]}" "$SELF_IP"; do
  [ "$VIP" != "$ip" ] || die "VIP $VIP matches a node address"
done

# Install all dependencies before generating or replacing configuration.
inf "Checking LB dependencies"
if [ "$CHECK_ONLY" -eq 1 ]; then
  command -v haproxy >/dev/null || die 'HAProxy must already be installed for --check-only'
  command -v keepalived >/dev/null || die 'Keepalived must already be installed for --check-only'
  command -v python3 >/dev/null || die 'Python 3 must already be installed for --check-only'
else
  apt-get update -qq
  apt-get install -y -qq haproxy keepalived psmisc python3 >/dev/null
fi
if [ "$CHECK_ONLY" -eq 1 ]; then
  [ "$(sysctl -n net.ipv4.ip_nonlocal_bind)" = 1 ] \
    && grep -Fxq 'net.ipv4.ip_nonlocal_bind = 1' "$NONLOCAL_CONF" \
    || die 'VIP-specific listeners require persistent net.ipv4.ip_nonlocal_bind=1; rerun LB setup'
fi

inf "Generating HAProxy configuration"
TMP_CFG="$(mktemp)"
cat > "$TMP_CFG" <<EOF
# Kubernetes clients keep long-lived connections to this TCP frontend.

global
    log /dev/log local0
    log /dev/log local1 notice
    daemon
    maxconn 4000
    stats socket /run/haproxy/admin.sock mode 660 level admin
    stats timeout 30s

defaults
    log     global
    mode    tcp
    retries 3
    timeout connect 10s
    timeout client  1m
    timeout server  1m
    timeout queue   1m
    option  tcplog

frontend kube-apiserver
    bind *:${API_PORT}
    mode tcp
    default_backend kube-apiserver-backend

backend kube-apiserver-backend
    mode tcp
    balance roundrobin
    # The API server is configured later by kubeadm; use a TCP health check.
    option tcp-check
EOF
for i in "${!BACKEND_NAMES[@]}"; do
  printf '    server %s %s:%s check fall 3 inter 2 rise 2\n' "${BACKEND_NAMES[$i]}" "${BACKEND_IPS[$i]}" "$API_PORT" >> "$TMP_CFG"
done
cat >> "$TMP_CFG" <<EOF

frontend stats
    bind *:7000
    mode http
    stats enable
    stats uri /
    stats refresh 10s
EOF

# Preserve routes owned by the post-deployment LB manager. Re-running cluster
# deployment must never replace these independently managed frontends/backends.
python3 - "$TMP_CFG" /etc/haproxy/haproxy.cfg <<'PY'
import pathlib, sys
candidate, current = map(pathlib.Path, sys.argv[1:])
begin, end = '# BEGIN ATLAS KUBEKIT MANAGED ROUTES', '# END ATLAS KUBEKIT MANAGED ROUTES'
text = current.read_text() if current.exists() else ''
starts, ends = text.count(begin), text.count(end)
if starts != ends or starts > 1:
    raise SystemExit('Existing HAProxy managed-route markers are incomplete or duplicated; refusing to replace the configuration')
if starts:
    if text.index(begin) >= text.index(end):
        raise SystemExit('Existing HAProxy managed-route markers are out of order')
    block = text[text.index(begin):text.index(end) + len(end)]
    generated = candidate.read_text()
    if begin in generated or end in generated:
        raise SystemExit('Generated HAProxy configuration unexpectedly contains managed-route markers')
    candidate.write_text(generated.rstrip() + '\n\n' + block + '\n')
PY

inf "Validating HAProxy configuration"
# 先校验临时文件，通过后才安装 —— 校验失败不会在 /etc 留下坏配置
if ! haproxy -c -f "$TMP_CFG"; then
  rm -f "$TMP_CFG"
  die "HAProxy config is invalid; existing config and service were not changed"
fi
pass "HAProxy candidate syntax validation passed"

# Keepalived's script-security check can reject a packaged command used
# directly as a tracking script. Install a small root-owned wrapper in a
# root-owned, non-writable directory and keep script security enabled.
if [ ! -x /usr/bin/killall ]; then
  die "Required HAProxy health-check dependency /usr/bin/killall is unavailable after installing psmisc; install psmisc and retry"
fi
CHECK_HAPROXY_SCRIPT=/usr/local/libexec/atlas-kubekit/check-haproxy
if [ "$CHECK_ONLY" -eq 1 ]; then
  [ -x "$CHECK_HAPROXY_SCRIPT" ] || die "Missing installed Keepalived health-check script: $CHECK_HAPROXY_SCRIPT"
else
  install -d -o root -g root -m 0755 /usr/local/libexec/atlas-kubekit
  TMP_CHECK="$(mktemp)"
  cat > "$TMP_CHECK" <<'EOF'
#!/bin/sh
exec /usr/bin/killall -0 haproxy
EOF
  if ! cmp -s "$TMP_CHECK" "$CHECK_HAPROXY_SCRIPT" 2>/dev/null \
    || [ "$(stat -c '%U:%G:%a' "$CHECK_HAPROXY_SCRIPT" 2>/dev/null || true)" != 'root:root:755' ]; then
    if [ -e "$CHECK_HAPROXY_SCRIPT" ]; then
      cp -a "$CHECK_HAPROXY_SCRIPT" "$CHECK_HAPROXY_SCRIPT.bak.$(date +%Y%m%d%H%M%S)"
    fi
    install -o root -g root -m 0755 "$TMP_CHECK" "$CHECK_HAPROXY_SCRIPT"
  fi
  rm -f "$TMP_CHECK"
fi
if [ "$(stat -c '%U:%G:%a' "$CHECK_HAPROXY_SCRIPT")" != 'root:root:755' ]; then
  die "Keepalived health-check script must be root:root mode 0755: $CHECK_HAPROXY_SCRIPT"
fi
pass "Keepalived HAProxy tracking script is installed securely"

TMP_KEEP="$(mktemp)"
TMP_STATE="$(mktemp)"
cat > "$TMP_KEEP" <<EOF
global_defs {
    script_user root
    enable_script_security
}

vrrp_script check_haproxy {
    script "${CHECK_HAPROXY_SCRIPT}"
    interval 2
    # Zero weight makes the VRRP instance enter FAULT if HAProxy is absent.
    weight 0
    fall 2
    rise 2
}

vrrp_instance VI_KUBE_APISERVER {
    state $(if [ "$MODE" = master ]; then printf MASTER; else printf BACKUP; fi)
    interface ${IFACE}
    virtual_router_id ${VRRP_ID}
    priority ${PRIORITY}
    advert_int 1

    authentication {
        auth_type PASS
        auth_pass ${AUTH_PASS}
    }

    virtual_ipaddress {
        ${VIP}
    }

    track_script {
        check_haproxy
    }
}
EOF

# Merge manager-owned VIPs into the generated Keepalived instance and retain
# its state file. The optional install-time ingress VIP becomes a normal
# managed VIP visible to 05-manage-lb.sh; routes are added later when a
# Gateway NodePort is known.
python3 - "$TMP_KEEP" /etc/keepalived/keepalived.conf /etc/atlas-kubekit/lb-manager.json "$TMP_STATE" "$APP_INGRESS_VIP" <<'PY'
import ipaddress, json, pathlib, re, sys
candidate, current, state_path, state_out = map(pathlib.Path, sys.argv[1:5])
requested = sys.argv[5]
begin, end = '# BEGIN ATLAS KUBEKIT MANAGED VIPS', '# END ATLAS KUBEKIT MANAGED VIPS'
state = {'vips': [], 'routes': []}
if state_path.exists():
    state = json.loads(state_path.read_text())
    if not isinstance(state, dict) or not isinstance(state.get('vips'), list) or not isinstance(state.get('routes'), list):
        raise SystemExit('Existing LB manager state is invalid; refusing to replace Keepalived configuration')
if state['routes']:
    haproxy = pathlib.Path('/etc/haproxy/haproxy.cfg')
    if not haproxy.exists() or '# BEGIN ATLAS KUBEKIT MANAGED ROUTES' not in haproxy.read_text():
        raise SystemExit('LB manager state contains routes but HAProxy has no managed-route block')
vips = state['vips']
for value in vips:
    try: ipaddress.IPv4Address(value)
    except Exception: raise SystemExit(f'Invalid VIP in LB manager state: {value}')
vips.sort(key=lambda value: int(ipaddress.IPv4Address(value)))

old_text = current.read_text() if current.exists() else ''
if old_text.count(begin) != old_text.count(end) or old_text.count(begin) > 1:
    raise SystemExit('Existing Keepalived managed-VIP markers are incomplete or duplicated; refusing to replace the configuration')
if old_text.count(begin):
    if old_text.index(begin) >= old_text.index(end):
        raise SystemExit('Existing Keepalived managed-VIP markers are out of order')
    old_block = old_text[old_text.index(begin):old_text.index(end) + len(end)]
    old_values = re.findall(r'(?m)^\s*([0-9]+(?:\.[0-9]+){3})\s*$', old_block)
    if sorted(old_values, key=lambda value: int(ipaddress.IPv4Address(value))) != vips:
        raise SystemExit('Existing Keepalived managed VIPs do not match the manager state; reconcile them before rerunning deployment')
elif vips:
    raise SystemExit('LB manager state contains business VIPs but Keepalived has no managed-VIP block; refusing to lose them')

# Compare the persisted state first; a newly requested VIP is not present yet.
if requested:
    try: ipaddress.IPv4Address(requested)
    except Exception: raise SystemExit('Application ingress VIP is not a valid IPv4 address')
    if requested not in vips: vips.append(requested)
vips.sort(key=lambda value: int(ipaddress.IPv4Address(value)))

text = candidate.read_text()
matches = list(re.finditer(r'(virtual_ipaddress\s*\{)([^}]*)(\})', text, re.S))
if len(matches) != 1: raise SystemExit('Generated Keepalived configuration must contain exactly one virtual_ipaddress block')
if vips:
    block = begin + '\n' + ''.join('        ' + value + '\n' for value in vips) + end + '\n'
    match = matches[0]
    body = match.group(2)
    if begin in body or end in body: raise SystemExit('Generated Keepalived configuration unexpectedly contains managed-VIP markers')
    text = text[:match.start()] + match.group(1) + body.rstrip() + '\n' + block + match.group(3) + text[match.end():]
candidate.write_text(text)
state['vips'] = vips
state.setdefault('routes', [])
state_out.write_text(json.dumps(state, indent=2) + '\n')
PY

keepalived -t -f "$TMP_KEEP" || { rm -f "$TMP_KEEP"; die "Keepalived config validation failed; existing config was not changed"; }
if [ "$CHECK_ONLY" -eq 1 ]; then
  "$CHECK_HAPROXY_SCRIPT" >/dev/null 2>&1 || die 'The installed tracking script cannot detect HAProxy'
  pass "Check-only complete; no services or files were changed"
  exit 0
fi

# Validate both candidates before changing either live configuration. Snapshot
# all managed files so ERR/exit failures also reach the rollback path.
NONLOCAL_BIND_BEFORE="$(sysctl -n net.ipv4.ip_nonlocal_bind)"
case "$NONLOCAL_BIND_BEFORE" in 0|1) ;; *) die 'Cannot read net.ipv4.ip_nonlocal_bind';; esac
TMP_SYSCTL="$(mktemp)"
printf '# Permit VIP-specific HAProxy listeners on standby nodes.\nnet.ipv4.ip_nonlocal_bind = 1\n' > "$TMP_SYSCTL"
install -d -o root -g root -m 0700 /var/backups/atlas-kubekit/lb-setup
BACKUP_DIR="$(mktemp -d /var/backups/atlas-kubekit/lb-setup/run.XXXXXXXX)"
printf '%s\n' "${CONFIG_PATHS[@]}" > "$BACKUP_DIR/paths"
for i in "${!CONFIG_PATHS[@]}"; do
  if [ -e "${CONFIG_PATHS[$i]}" ] || [ -L "${CONFIG_PATHS[$i]}" ]; then
    cp -a "${CONFIG_PATHS[$i]}" "$BACKUP_DIR/$i"
  else
    touch "$BACKUP_DIR/$i.absent"
  fi
done
for i in "${!SERVICES[@]}"; do
  if systemctl is-active --quiet "${SERVICES[$i]}"; then SERVICE_ACTIVE[$i]=1; fi
  if systemctl is-enabled --quiet "${SERVICES[$i]}"; then SERVICE_ENABLED[$i]=1; fi
  printf '%s active=%s enabled=%s\n' "${SERVICES[$i]}" "${SERVICE_ACTIVE[$i]}" "${SERVICE_ENABLED[$i]}" >> "$BACKUP_DIR/services"
done
ROLLBACK_REQUIRED=1
for i in "${!SERVICES[@]}"; do
  SERVICE_ENABLE_TOUCHED[$i]=1
  systemctl enable "${SERVICES[$i]}" >/dev/null || die "Cannot enable ${SERVICES[$i]} at boot"
  systemctl is-enabled --quiet "${SERVICES[$i]}" || die "${SERVICES[$i]} is not enabled at boot"
done
install -d -m 0755 /run/haproxy /etc/atlas-kubekit /etc/sysctl.d
HAPROXY_CHANGED=0 KEEPALIVED_CHANGED=0
if ! cmp -s "$TMP_CFG" /etc/haproxy/haproxy.cfg; then
  HAPROXY_CHANGED=1
fi
if ! cmp -s "$TMP_KEEP" /etc/keepalived/keepalived.conf; then
  KEEPALIVED_CHANGED=1
fi
# Reinstall matching bytes too, so reruns also correct ownership and modes.
install -o root -g root -m 0644 "$TMP_CFG" /etc/haproxy/haproxy.cfg
install -o root -g root -m 0640 "$TMP_KEEP" /etc/keepalived/keepalived.conf
install -o root -g root -m 0600 "$TMP_STATE" /etc/atlas-kubekit/lb-manager.json
install -o root -g root -m 0644 "$TMP_SYSCTL" "$NONLOCAL_CONF"
if [ "$NONLOCAL_BIND_BEFORE" != 1 ]; then
  NONLOCAL_BIND_TOUCHED=1
  sysctl -w net.ipv4.ip_nonlocal_bind=1 >/dev/null || die 'Cannot enable VIP-specific HAProxy listeners'
fi
[ "$(sysctl -n net.ipv4.ip_nonlocal_bind)" = 1 ] || die 'net.ipv4.ip_nonlocal_bind did not become effective'
haproxy -c -f /etc/haproxy/haproxy.cfg || die 'Installed HAProxy configuration failed validation'
keepalived -t -f /etc/keepalived/keepalived.conf || die 'Installed Keepalived configuration failed validation'
if [ "$HAPROXY_CHANGED" -eq 1 ] || [ "${SERVICE_ACTIVE[0]}" -eq 0 ]; then
  SERVICE_TOUCHED[0]=1
  systemctl restart haproxy || die 'HAProxy restart failed; restoring the previous configuration'
fi
systemctl is-active --quiet haproxy || die 'HAProxy did not remain active'
"$CHECK_HAPROXY_SCRIPT" >/dev/null 2>&1 || die 'The tracking script cannot detect the running HAProxy process'
if [ "$KEEPALIVED_CHANGED" -eq 1 ] || [ "${SERVICE_ACTIVE[1]}" -eq 0 ]; then
  SERVICE_TOUCHED[1]=1
  systemctl restart keepalived || die 'Keepalived restart failed; restoring the previous configuration'
fi
sleep 2
systemctl is-active --quiet haproxy && systemctl is-active --quiet keepalived || die 'LB services did not remain active'
ss -H -lnt "sport = :${API_PORT}" | grep -q . || die 'HAProxy API port is not listening'
ROLLBACK_REQUIRED=0
pass "HAProxy and Keepalived are running and enabled at boot (role=$MODE)"

# ============================================================== 3. 自检
hdr() { printf '\n\033[1;36m===== %s =====\033[0m\n' "$*"; }
hdr "Self-check"

# 本机 VIP 是否已生效
if ip -o -4 addr show "$IFACE" | awk -v vip="$VIP" '{split($4, a, "/"); if (a[1] == vip) found=1} END {exit !found}'; then
  pass "VIP $VIP is present locally (MASTER)"
else
  pass "VIP $VIP is not local yet (BACKUP or VRRP election in progress)"
fi

# The control-plane API is not listening until kubeadm init; verify HAProxy itself here.
inf "Checking local API port listener"
ss -lntp "sport = :${API_PORT}" || warn 'Could not display the API listener details'

cat <<EOF

$(grn "============================================================")
$(grn " LB setup complete")
$(grn "============================================================")
  VIP for kubeadm     : ${VIP}:${API_PORT}
$(if [ -n "$APP_INGRESS_VIP" ]; then printf '  Application VIP    : %s (route configured after Gateway install)\n' "$APP_INGRESS_VIP"; fi)
  HAProxy stats       : http://${SELF_IP}:7000
  VRRP virtual_router_id : ${VRRP_ID}
  VRRP auth_pass     : [configured, hidden]
  Local role         : ${MODE^^} (priority=${PRIORITY})

$(red "  Use the same VRRP ID, password, and VIP on every LB:")
$(red "    virtual_router_id = ${VRRP_ID}")
$(red "    auth_pass         = same value on every LB (hidden)")
$(red "    virtual_ipaddress = ${VIP}")
$(red "    local interface   = ${IFACE} (may differ on other LBs)")
$(red "  A mismatched auth_pass can make multiple LBs MASTER and cause an IP conflict.")
$(red "  Each LB must have a distinct priority.")

  After setting up all LBs, check which one is MASTER:
    ip -br addr show ${IFACE} | grep ${VIP}

$(red "  kubeadm controlPlaneEndpoint must be ${VIP}:${API_PORT}.")
$(red "  Changing it later requires a separate migration.")

  Next: 02-deploy-cluster.sh configures and initializes cp1.
$(grn "============================================================")
